const canvas=document.getElementById('view'),ctx=canvas.getContext('2d',{alpha:false}),$=id=>document.getElementById(id);
const ui={overlay:$('overlay'),title:$('title'),copy:$('copy'),kicker:$('kicker'),hint:$('hint'),start:$('start'),teamselect:$('teamselect'),teamPill:$('teamPill'),hp:$('hp'),hpLabel:$('hpLabel'),healthBar:$('healthBar'),armorLabel:$('armorLabel'),armorBar:$('armorBar'),hostiles:$('hostiles'),round:$('round'),objective:$('objective'),ammo:$('ammo'),reserve:$('reserve'),weapon:$('weapon'),toast:$('toast'),hit:$('hitmarker'),damage:$('damage'),crosshair:$('crosshair'),knob:$('knob')};
const map=[
'1111111111111111','1000000000000001','1020000000000201','1000000000000001','1000110000110001','1000100000010001','1000000000000001','1002000000000201','1000000000000001','1000110000110001','1000100000010001','1000000000000001','1020000000000201','1000000000000001','1000000000000001','1111111111111111'];
const MW=16,MH=16,FOV=Math.PI/2.95,TAU=Math.PI*2,clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),rand=(a,b)=>a+Math.random()*(b-a),norm=a=>Math.atan2(Math.sin(a),Math.cos(a));
let W=640,H=400,dpr=1,zbuf=new Float32Array(W),last=0,state='title',selected='ct',keys={},player={x:8.1,y:12.3,a:-Math.PI/2,hp:100,armor:75,ammo:30,reserve:90,reload:0,shot:0,kick:0,bob:0,hit:0,dead:false},bots=[],round=1,kills=0,fireHeld=false,fireTimer=0,toastTimer=0,damageTimer=0,shake=0,joy={x:0,y:0},joystick=null,dragLook=null,prevFrame=performance.now(),lastShot=0;
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,1.35);W=Math.max(360,Math.round(r.width*dpr*.82));H=Math.max(240,Math.round(r.height*dpr*.82));canvas.width=W;canvas.height=H;zbuf=new Float32Array(W)}new ResizeObserver(resize).observe(canvas);resize();
function wall(x,y){x=Math.floor(x);y=Math.floor(y);return x<0||y<0||x>=MW||y>=MH||map[y][x]!=='0'}
function canMove(x,y,r=.22){return !wall(x-r,y-r)&&!wall(x+r,y-r)&&!wall(x-r,y+r)&&!wall(x+r,y+r)}
function clearShot(x1,y1,x2,y2){let dx=x2-x1,dy=y2-y1,n=Math.ceil(Math.hypot(dx,dy)*9);for(let i=1;i<n;i++){let t=i/n;if(wall(x1+dx*t,y1+dy*t))return false}return true}
function spawnBots(count=5){bots=[];let tries=0;while(bots.length<count&&tries++<900){let x=rand(2,14),y=rand(2,14);if(wall(x,y)||Math.hypot(x-player.x,y-player.y)<5||bots.some(b=>Math.hypot(x-b.x,y-b.y)<2))continue;bots.push({x,y,hp:100,alive:true,angle:rand(-Math.PI,Math.PI),move:rand(0,TAU),think:rand(.3,1),shoot:rand(.6,1.6),flash:0,hit:0,walk:rand(0,6),team:selected==='ct'?'t':'ct',strafe:Math.random()<.5?-1:1})}}
function setTeam(t){selected=t;document.querySelectorAll('.team').forEach(b=>b.classList.toggle('selected',b.dataset.team===t));$('teamPill').innerHTML=t==='ct'?'<b>CT</b> · ALPHA':'<b>INS</b> · BRAVO';$('weapon').textContent=t==='ct'?'M4A1 · 5.56MM':'AK-47 · 7.62MM'}
document.querySelectorAll('.team').forEach(b=>b.onclick=()=>setTeam(b.dataset.team));
function startGame(){player={x:8.1,y:12.5,a:-Math.PI/2,hp:100,armor:75,ammo:30,reserve:90,reload:0,shot:0,kick:0,bob:0,hit:0,dead:false};round=1;kills=0;spawnBots(5);state='playing';ui.overlay.classList.add('hidden');notify('BREACH THE OUTPOST');updateHud();if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.()}
function showOverlay(kind){state=kind;ui.overlay.classList.remove('hidden');ui.teamselect.style.display=kind==='title'?'grid':'none';if(kind==='title'){ui.kicker.textContent='TACTICAL SIMULATION · 01';ui.title.innerHTML='Choose your<br>side.';ui.copy.textContent='A hostile squad has seized the Dustline outpost. Pick a team, breach the perimeter, and clear the site. Your squad is counting on you.';ui.start.innerHTML='DEPLOY TO DUSTLINE&nbsp; →';ui.hint.innerHTML='Move: WASD / left stick &nbsp; · &nbsp; Aim: mouse / drag &nbsp; · &nbsp; Fire: click / FIRE'}else if(kind==='pause'){ui.kicker.textContent='MISSION PAUSED';ui.title.innerHTML='Take a breath.';ui.copy.textContent='The outpost is still hot. Your squad is holding position.';ui.start.textContent='RESUME MISSION';ui.hint.textContent='Tap resume to return to the fight.'}else{ui.kicker.textContent=kind==='won'?'MISSION COMPLETE':'OPERATOR DOWN';ui.title.innerHTML=kind==='won'?'Outpost<br>secured.':'Mission<br>failed.';ui.copy.textContent=kind==='won'?`Dustline is clear. ${kills} hostiles neutralized. Your team owns the site.`:'You were overwhelmed in the Dustline. Regroup and go again.';ui.start.textContent='DEPLOY AGAIN  →';ui.hint.textContent='Tap to run the operation again.'}}
ui.start.addEventListener('click',()=>state==='pause'?resume():startGame());$('pauseBtn').onclick=()=>state==='playing'?pause():state==='pause'?resume():null;
function pause(){state='pause';ui.overlay.classList.remove('hidden');document.exitPointerLock?.()}function resume(){state='playing';ui.overlay.classList.add('hidden');if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.()}
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('on');toastTimer=1.35}
function updateHud(){ui.hp.textContent=Math.ceil(player.hp);ui.hpLabel.textContent=Math.ceil(player.hp);ui.healthBar.style.width=player.hp+'%';ui.armorLabel.textContent=Math.ceil(player.armor);ui.armorBar.style.width=player.armor/75*100+'%';ui.ammo.textContent=player.ammo;ui.reserve.textContent=player.reserve;ui.hostiles.textContent=String(bots.filter(b=>b.alive).length).padStart(2,'0');ui.round.textContent='ROUND '+String(round).padStart(2,'0')}
function reload(){if(state!=='playing'||player.reload>0||player.ammo===30||player.reserve<=0)return;player.reload=1.35;notify('RELOADING')}
function shoot(){if(state!=='playing'||player.reload>0||performance.now()-lastShot<135)return;lastShot=performance.now();if(player.ammo<=0){reload();return}player.ammo--;player.shot=.09;player.kick=1;fireTimer=.13;let spread=(Math.random()-.5)*.035+(player.bob?0:0),angle=player.a+spread,best=null,bestDist=15;for(const b of bots){if(!b.alive)continue;let dx=b.x-player.x,dy=b.y-player.y,dist=Math.hypot(dx,dy),diff=Math.abs(norm(Math.atan2(dy,dx)-angle));let thresh=Math.atan2(.32,dist);if(diff<thresh&&dist<bestDist&&clearShot(player.x,player.y,b.x,b.y)){best=b;bestDist=dist}}if(best){best.hp-=selected==='ct'?38:43;best.hit=.18;ui.hit.classList.add('show');setTimeout(()=>ui.hit.classList.remove('show'),100);if(best.hp<=0){best.alive=false;kills++;notify(Math.random()<.4?'HOSTILE DOWN':'TARGET ELIMINATED');if(kills%3===0)player.hp=Math.min(100,player.hp+8);if(!bots.some(b=>b.alive)){if(round<3){round++;player.hp=Math.min(100,player.hp+20);player.armor=Math.min(75,player.armor+15);spawnBots(5+round);notify('AREA CLEAR · NEXT WAVE')}else{updateHud();setTimeout(()=>showOverlay('won'),850)}}}}updateHud()}
function hitPlayer(dmg){let absorb=Math.min(player.armor,dmg*.55);player.armor-=absorb;player.hp=Math.max(0,player.hp-(dmg-absorb));ui.damage.classList.add('on');damageTimer=.2;shake=3;updateHud();if(player.hp<=0){player.dead=true;setTimeout(()=>showOverlay('dead'),500)}}

function castRay(angle){let dx=Math.cos(angle),dy=Math.sin(angle),mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/dx),ddy=Math.abs(1/dy),sx=dx<0?-1:1,sy=dy<0?-1:1,sdx=(dx<0?player.x-mx:mx+1-player.x)*ddx,sdy=(dy<0?player.y-my:my+1-player.y)*ddy,side=0,steps=0;while(steps++<45){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(mx<0||my<0||mx>=MW||my>=MH||map[my][mx]!=='0')break}let d=side? sdy-ddy:sdx-ddx;let wallX=side?player.x+Math.cos(angle)*d:player.y+Math.sin(angle)*d;wallX-=Math.floor(wallX);return{d:Math.max(.001,d),side,wallX,mx,my,type:map[my]?.[mx]||'1'}}
function drawWorld(t){let sky=ctx.createLinearGradient(0,0,0,H*.57);sky.addColorStop(0,'#9b7955');sky.addColorStop(.47,'#d7ad73');sky.addColorStop(1,'#64604e');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H*.56);ctx.fillStyle='#817453';ctx.fillRect(0,H*.55,W,H*.45);
// distant ridge and bright desert horizon
ctx.fillStyle='#6c6550';ctx.beginPath();ctx.moveTo(0,H*.52);for(let x=0;x<=W;x+=W/8)ctx.lineTo(x,H*(.46+Math.sin(x*.019)*.03+Math.sin(x*.041)*.013));ctx.lineTo(W,H*.66);ctx.lineTo(0,H*.66);ctx.fill();let horizon=H*.53;
let floor=ctx.createLinearGradient(0,horizon,0,H);floor.addColorStop(0,'#8b7959');floor.addColorStop(.32,'#625640');floor.addColorStop(1,'#262d29');ctx.fillStyle=floor;ctx.fillRect(0,horizon,W,H-horizon);
// receding ground seams
ctx.strokeStyle='#e7c68b18';ctx.lineWidth=1;for(let i=1;i<13;i++){let y=horizon+(H-horizon)*(i/13)**2;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}for(let i=-8;i<=8;i++){ctx.beginPath();ctx.moveTo(W/2+i*2,H);ctx.lineTo(W/2+i*20,horizon);ctx.stroke()}
